import{_ as r,o as t,c as n,a3 as i}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/unterricht-kataloge/kataloge-orte.png",p=JSON.parse('{"title":"Orte und ihre Reihenfolge verwalten","description":"","frontmatter":{"title":"Orte und ihre Reihenfolge verwalten","source_pageid":377,"source_revision":4421},"headers":[],"relativePath":"schild3/unterricht-kataloge/orte-allgemeine-kataloge.md","filePath":"schild3/unterricht-kataloge/orte-allgemeine-kataloge.md"}'),l={name:"schild3/unterricht-kataloge/orte-allgemeine-kataloge.md"};function o(s,e,g,d,h,u){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="orte-und-ihre-reihenfolge-verwalten" tabindex="-1">Orte und ihre Reihenfolge verwalten <a class="header-anchor" href="#orte-und-ihre-reihenfolge-verwalten" aria-label="Permalink to &quot;Orte und ihre Reihenfolge verwalten&quot;">​</a></h1><p>Ergänzen Sie Orte und bestimmen Sie, ob die Auswahlliste nach Postleitzahl, Ortsname oder einer eigenen Reihenfolge sortiert wird.</p><p><a href="/bilder/unterricht-kataloge/kataloge-orte.png"><img src="'+a+'" alt="Pflege der zur Verfügung stehenden Orte." loading="lazy"></a></p><p><em>Pflege der zur Verfügung stehenden Orte.</em></p><p>Sie können die über Dropdown-Menüs verfügbaren Orte über <em>Kataloge ➜ Orte</em> einstellen.</p><p>Per Standard ist die Liste nach Postleitzahlen sortiert, stellen Sie unter <strong>Sortierung</strong> auf <em>Ortsname</em> oder <em>Benutzerdefiniert</em> um.</p><p>Verändern Sie bei der benutzerdefinierten Sortierung mit den Pfeilen links oben die Reihenfolge, um oft verwendete Orte in der Liste nach oben zu schieben.</p><p>Wie in allen Katalogen lassen sich Einträge mit dem <strong>+</strong> und dem <strong>-</strong> hinzufügen und entfernen.</p><p>Ein Klick auf <em>Excel-Export</em> erzeugt eine Excel-Liste der Katalogeinträge.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Orte_(Allgemeine_Kataloge)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 4421.</p>',11)])])}const c=r(l,[["render",o]]);export{p as __pageData,c as default};
